$ErrorActionPreference = "Stop"

$Repo = "C:\Users\nhann\Documents\GitHub\Photon-Camera-clean-rebuild"
$Generated = Join-Path $Repo "build_26445_specular_channel_validity_v2.generated.ps1"

if (-not (Test-Path -LiteralPath $Repo)) {
    throw "FAIL: repository path not found"
}

[IO.File]::WriteAllBytes(
    $Generated,
    [Convert]::FromBase64String("")
)

$GeneratedText = [IO.File]::ReadAllText($Generated)
foreach ($Forbidden in @(
    "foreach(",
    "in@(",
    "-LiteralPath("
)) {
    if ($GeneratedText.Contains($Forbidden)) {
        throw ("FAIL: unsafe compact PowerShell syntax survived: " + $Forbidden)
    }
}

$Tokens = $null
$ParseErrors = $null
[System.Management.Automation.Language.Parser]::ParseFile(
    $Generated,
    [ref]$Tokens,
    [ref]$ParseErrors
) | Out-Null

if ($ParseErrors.Count -gt 0) {
    Write-Host "26445 V2 PARSER GATE FAILED" -ForegroundColor Red
    foreach ($ParseError in $ParseErrors) {
        Write-Host (
            "Line " + $ParseError.Extent.StartLineNumber +
            ": " + $ParseError.Message
        ) -ForegroundColor Red
    }
    throw "FAIL: generated 26445 v2 script has parser errors. Nothing executed."
}

Write-Host "PASS: 26445 V2 FULL-SCRIPT PARSER GATE" -ForegroundColor Green
& $Generated
